package distributions
import("testing";"time")
func TestDeploymentPreviewBindsDistributionGroupAndContent(t *testing.T){d,err:=New("Platform Collector","0.140.0","v0.140.0","","",ComponentSet{Receivers:[]string{"otlp"}},nil,[]string{"receivers"},"admin",time.Unix(1,0));if err!=nil{t.Fatal(err)};one,err:=NewDeploymentPreview(d,"payments","Payments",map[string]string{"receivers":"otlp: {}"},"receivers:\n  otlp: {}","{\"valid\":true}","operator",time.Unix(2,0));if err!=nil{t.Fatal(err)};two,err:=NewDeploymentPreview(d,"payments","Payments",map[string]string{"receivers":"otlp: {}"},"receivers:\n  otlp: {}","{\"valid\":true}","operator",time.Unix(3,0));if err!=nil{t.Fatal(err)};if one.ID!=two.ID||one.ContentHash!=two.ContentHash{t.Fatalf("preview evidence is not stable: %#v %#v",one,two)};if one.DistributionSpecHash!=d.SpecHash{t.Fatal("distribution evidence was not bound")}}
